// Reopening the database that was used last time. Only the descriptor (id,
// label, path) is restored; the master password is never persisted, so the
// unlock screen still asks for it.

import type { DatabaseDescriptor, RemoteDatabase } from './descriptor';
import type { StoredDatabase } from './registry';
import {
  forget,
  getLastOpenedId,
  listRemembered,
  remember,
  setLastOpenedId,
} from './registry';
import { lookupDatabase } from './remote';

/**
 * Adopt a remembered database under its current file id. A re-created
 * Nextcloud instance (or a restore from backup) hands out new file ids for the
 * same paths, which would otherwise leave a stale, "file not found" entry.
 */
export async function adoptRemoteId(
  remembered: StoredDatabase,
  found: RemoteDatabase,
): Promise<DatabaseDescriptor> {
  const descriptor: DatabaseDescriptor = {
    id: found.id,
    label: remembered.label,
    path: found.path,
    canWrite: found.canWrite,
  };
  // Read the marker before `forget` clears it for the old id.
  const wasLastOpened = (await getLastOpenedId()) === remembered.id;
  await remember(descriptor);
  await forget(remembered.id);
  if (wasLastOpened) {
    await setLastOpenedId(descriptor.id);
  }
  return descriptor;
}

/**
 * The descriptor of the database that was opened last, or null when there is
 * none (or when its file has gone). Throws only on a transport failure, so the
 * caller can fall back to the database list.
 */
export async function restoreLastOpened(): Promise<DatabaseDescriptor | null> {
  const id = await getLastOpenedId();
  if (id === null) {
    return null;
  }
  const remembered = (await listRemembered()).find((item) => item.id === id);
  if (remembered === undefined) {
    // The entry was removed from the list (or the registry was wiped).
    await setLastOpenedId(null);
    return null;
  }

  const found = await lookupDatabase(remembered.path);
  if (found === null) {
    // Keep the label so the list can show it as missing.
    return null;
  }
  if (found.id !== remembered.id) {
    return adoptRemoteId(remembered, found);
  }

  const descriptor: DatabaseDescriptor = {
    id: found.id,
    label: remembered.label,
    path: found.path,
    canWrite: found.canWrite,
  };
  await remember(descriptor);
  return descriptor;
}
